    // Krafttraining (RenfoGuide)
    "renfo.banner.title": "Krafteinheit.", "renfo.banner.body": "Wähle je nach heutiger Ausrüstung 👇 — 5-10 Min. aufwärmen, dann die Blöcke durchziehen (20-30 Min., 1-2×/Woche). Qualität > Quantität: langsame, kontrollierte Bewegungen.", "renfo.demo": "Video-Demo ansehen",
    "renfo.prog.none.label": "Ohne Geräte", "renfo.prog.none.intro": "Nur mit dem eigenen Körpergewicht — zu Hause, unterwegs, im Park. Keine Ausrüstung, keine Ausreden.",
    "renfo.prog.home.label": "Zu Hause (Bänder + Hanteln)", "renfo.prog.home.intro": "Mit etwas Ausrüstung zu Hause: Widerstandsbänder und/oder Hanteln (oder ein beladener Rucksack, Wasserflaschen).",
    "renfo.prog.gym.label": "Fitnessstudio", "renfo.prog.gym.intro": "Im Studio, mit Langhanteln, Maschinen und Gewichten: maximale Kraft für den Läufer (schwere Bewegungen, wenige Wiederholungen).",
    "renfo.none.b1.group": "Core / Rumpf", "renfo.none.b1.intro": "Ein stabiler Rumpf = stabiles Becken und weniger Energieverlust bei jedem Schritt.",
    "renfo.none.b1.e1.name": "Unterarmstütz", "renfo.none.b1.e1.dose": "3 × 45 s", "renfo.none.b1.e1.cue": "Körper Fersen-Becken-Schultern in einer Linie, Bauch und Gesäß angespannt, Rücken nicht durchhängen lassen.",
    "renfo.none.b1.e2.name": "Seitstütz", "renfo.none.b1.e2.dose": "3 × 30 s / Seite", "renfo.none.b1.e2.cue": "Auf dem Unterarm, Hüfte hoch. Stärkt die schrägen Bauchmuskeln und den mittleren Gesäßmuskel (Beckenstabilität).",
    "renfo.none.b1.e3.name": "Dead Bug", "renfo.none.b1.e3.dose": "3 × 10 / Seite", "renfo.none.b1.e3.cue": "Auf dem Rücken, gegenüberliegenden Arm + Bein senken, ohne den unteren Rücken abzuheben.",
    "renfo.none.b1.e4.name": "Mountain Climbers", "renfo.none.b1.e4.dose": "3 × 30 s", "renfo.none.b1.e4.cue": "Im Stütz die Knie abwechselnd heranziehen, Rumpf stabil, kontrolliertes Tempo.",
    "renfo.none.b2.group": "Hintere Kette & Gesäß", "renfo.none.b2.intro": "Der Motor des Läufers: Gesäß und Beinbeuger schützen die Knie und treiben dich an.",
    "renfo.none.b2.e1.name": "Beckenheben", "renfo.none.b2.e1.dose": "3 × 15", "renfo.none.b2.e1.cue": "Becken anheben und das Gesäß oben fest anspannen, Füße flach.",
    "renfo.none.b2.e2.name": "Einbeiniges Beckenheben", "renfo.none.b2.e2.dose": "3 × 10 / Bein", "renfo.none.b2.e2.cue": "Ein Bein gestreckt, mit dem anderen das Becken anheben. Schwieriger, gegen Dysbalancen.",
    "renfo.none.b2.e3.name": "Ausfallschritte vorwärts", "renfo.none.b2.e3.dose": "3 × 10 / Bein", "renfo.none.b2.e3.cue": "Großer Schritt, hinteres Knie Richtung Boden, Oberkörper aufrecht, vorderes Knie hinter den Zehen.",
    "renfo.none.b2.e4.name": "Kniebeugen mit Körpergewicht", "renfo.none.b2.e4.dose": "3 × 15", "renfo.none.b2.e4.cue": "Gesäß nach hinten schieben, Rücken gerade, Oberschenkel waagerecht, Gewicht auf den Fersen.",
    "renfo.none.b3.group": "Waden & Füße", "renfo.none.b3.intro": "Verletzungszone Nr. 1 des Läufers (Achillessehne, Schienbeinkantensyndrom). Unbedingt zu kräftigen.",
    "renfo.none.b3.e1.name": "Wadenheben", "renfo.none.b3.e1.dose": "3 × 15", "renfo.none.b3.e1.cue": "Auf einer Stufe langsam auf die Zehen, unter die Waagerechte absenken. Auch mit gebeugtem Knie (Schollenmuskel).",
    "renfo.none.b3.e2.name": "Exzentrisch Achillessehne", "renfo.none.b3.e2.dose": "3 × 12", "renfo.none.b3.e2.cue": "Auf 2 Füßen hoch, langsam auf nur 1 ab. Sehnenprävention +++.",
    "renfo.none.b4.group": "Gleichgewicht & Explosivität", "renfo.none.b4.intro": "Stabilität, Reaktionsfähigkeit des Fußes, Vorbeugung von Verstauchungen (besonders im Trail).",
    "renfo.none.b4.e1.name": "Einbeiniges Gleichgewicht", "renfo.none.b4.e1.dose": "3 × 30 s / Fuß", "renfo.none.b4.e1.cue": "Auf einem Fuß, Knie locker. Steigerung: Augen geschlossen, dann auf einem Kissen.",
    "renfo.none.b4.e2.name": "Squat Jump", "renfo.none.b4.e2.dose": "3 × 10", "renfo.none.b4.e2.cue": "Kniebeuge, dann explosiver Sprung, weiche Landung auf dem Vorfuß. Elastische Steifigkeit.",
    "renfo.home.b1.group": "Core / Rumpf", "renfo.home.b1.intro": "Wir fügen Widerstand und Anti-Rotation hinzu.",
    "renfo.home.b1.e1.name": "Pallof Press (Band)", "renfo.home.b1.e1.dose": "3 × 12 / Seite", "renfo.home.b1.e1.cue": "Band seitlich, Arme nach vorne strecken und der Rotation widerstehen. Anti-Rotation = Schlüssel für nützliche Rumpfarbeit.",
    "renfo.home.b1.e2.name": "Unterarmstütz mit Gewicht", "renfo.home.b1.e2.dose": "3 × 40 s", "renfo.home.b1.e2.cue": "Stütz mit einer Hantel oder einem Rucksack auf dem oberen Rücken. Bleibe perfekt stabil.",
    "renfo.home.b1.e3.name": "Russian Twist (Hantel)", "renfo.home.b1.e3.dose": "3 × 16", "renfo.home.b1.e3.cue": "Sitzend, Oberkörper zurückgelehnt, Rumpf mit einem Gewicht drehen. Schräge Bauchmuskeln.",
    "renfo.home.b2.group": "Hintere Kette & Gesäß", "renfo.home.b2.intro": "Der zusätzliche Widerstand maximiert den Kraftzuwachs.",
    "renfo.home.b2.e1.name": "Goblet Squat (Hantel)", "renfo.home.b2.e1.dose": "3 × 12", "renfo.home.b2.e1.cue": "Eine Hantel/Kettlebell an die Brust gehalten, tiefe Kniebeuge, gerader Rücken.",
    "renfo.home.b2.e2.name": "Rumänisches Kreuzheben (Hanteln)", "renfo.home.b2.e2.dose": "3 × 10", "renfo.home.b2.e2.cue": "Gerader Rücken, Hanteln an den Beinen entlang absenken und das Gesäß nach hinten schieben. Dehnt die Beinbeuger.",
    "renfo.home.b2.e3.name": "Ausfallschritte mit Hanteln", "renfo.home.b2.e3.dose": "3 × 10 / Bein", "renfo.home.b2.e3.cue": "Eine Hantel in jeder Hand, kontrollierter Ausfallschritt.",
    "renfo.home.b2.e4.name": "Hüftabduktion (Band)", "renfo.home.b2.e4.dose": "3 × 15 / Seite", "renfo.home.b2.e4.cue": "Band an Knöcheln/Knien, das Bein nach außen führen. Zielt auf den mittleren Gesäßmuskel (Beckenstabilität).",
    "renfo.home.b2.e5.name": "Beckenheben mit Gewicht", "renfo.home.b2.e5.dose": "3 × 12", "renfo.home.b2.e5.cue": "Beckenheben mit einer Hantel auf der Hüfte oder einem Band über den Knien.",
    "renfo.home.b3.group": "Waden & Haltung", "renfo.home.b3.intro": "Leichte Last, um Fortschritte zu machen.",
    "renfo.home.b3.e1.name": "Wadenheben mit Hanteln", "renfo.home.b3.e1.dose": "3 × 15", "renfo.home.b3.e1.cue": "Eine Hantel in jeder Hand, Wadenheben auf einer Stufe.",
    "renfo.home.b3.e2.name": "Bandrudern (Rücken/Haltung)", "renfo.home.b3.e2.dose": "3 × 15", "renfo.home.b3.e2.cue": "Band vorne befestigt, ziehen und die Schulterblätter zusammenführen. Verbessert die Laufhaltung.",
    "renfo.home.b4.group": "Gleichgewicht & Explosivität",
    "renfo.home.b4.e1.name": "Sprung-Ausfallschritt", "renfo.home.b4.e1.dose": "3 × 8 / Bein", "renfo.home.b4.e1.cue": "Ausfallschritt, dann Sprung mit Beinwechsel in der Luft. Kraft + Gleichgewicht.",
    "renfo.home.b4.e2.name": "Gleichgewicht + Hantel", "renfo.home.b4.e2.dose": "3 × 30 s / Fuß", "renfo.home.b4.e2.cue": "Auf einem Fuß eine Hantel um dich herum bewegen, um zu destabilisieren.",
    "renfo.gym.b1.group": "Kraft Unterkörper (schwer)", "renfo.gym.b1.intro": "Maximalkraft verbessert die Laufökonomie. Schwere Lasten, perfekte Technik.",
    "renfo.gym.b1.e1.name": "Langhantel-Kniebeuge", "renfo.gym.b1.e1.dose": "4 × 6-8", "renfo.gym.b1.e1.cue": "Stange auf dem Trapezmuskel, bis die Oberschenkel parallel sind, Rücken stabil. Progressive Last.",
    "renfo.gym.b1.e2.name": "Langhantel-Hip-Thrust", "renfo.gym.b1.e2.dose": "4 × 8", "renfo.gym.b1.e2.cue": "Rücken auf der Bank, Stange auf der Hüfte (Polster), drücken und das Gesäß oben anspannen.",
    "renfo.gym.b1.e3.name": "Bulgarische Kniebeuge (Hanteln)", "renfo.gym.b1.e3.dose": "3 × 8 / Bein", "renfo.gym.b1.e3.cue": "Hinterer Fuß auf einer Bank erhöht, senkrecht absenken. Einbeinig = gegen Dysbalancen.",
